/**
 * athleteRecord.ts — everything Nomila holds about one athlete, with provenance.
 *
 * Design: The Athlete Record (6 Sep 2026) + the Brand tab architecture. One read that the Facts
 * screen, the first entry and Mila can all draw from, so "what Mila knows" and "what the athlete
 * sees" cannot drift. Every entry says what kind of fact it is:
 *
 *   said   the athlete's own words — the ledger (athlete_asserted), or a signup column
 *   found  research, connected accounts, the inbox
 *   made   computed or generated by us
 *   proof  a contract on file or an accepted deal — the only kind that scores
 *
 * and where it came from and when, so the screen can print "you said · 4 Sep" or "found online".
 * Precedence is decided HERE, once: a said fact beats the found one for the same field.
 *
 * Nothing in this module writes. The write path is recordAssertions / clearAssertion in
 * server/mila/onboarding.ts; the Facts screen and the confirm cards both go through it.
 *
 * Six groups, in the order the athlete reads them. Numbers rows link out to the screens that own
 * them (Score, Rates, Growth); this read never duplicates analytics.
 */

import { readFollowers } from "./followers";
import { followersLine } from "./intelligence/context/views/record";
import { and, desc, eq, inArray, sql } from "drizzle-orm";
import { db } from "../db";
import {
  agentActions, deals, athleteSnapshots, athletes, athletesCurrent, connectedAccounts, socialAnalyticsSnapshots,
} from "../../shared/schema";
import {
  ASSERTED_FIELDS, latestAssertions, latestFirstLooks, type AssertedField, type AssertedFieldSpec,
  type AssertedShape,
} from "../mila/onboarding";
import { goalLabel, careerStatusLabel } from "../../shared/goals";
import { listAffiliations, displayTeam } from "./affiliations";
import { buildMyIntelligence } from "./intelligence/views/myIntelligence";

// Accepted deals count as proof on the athlete's OWN record whatever their source. The public
// deck keeps the stricter bar (snapshotDeals.confirmedPartnersFor: athlete-confirmed sources
// only) because it names a brand to other brands; this page is hers alone, and an accepted
// inbox deal is exactly the kind of fact she expects to see here.
const EARNED = ["accepted", "completed"] as const;
const ATHLETE_CONFIRMED = ["contract_upload", "self_reported"] as const;
const cadenceText = (perWeek: number | null | undefined): string | null => {
  if (perWeek == null || !Number.isFinite(perWeek)) return null;
  if (perWeek < 0.75) return "less than 1 a week";
  const n = Math.round(perWeek);
  return `about ${n} a week`;
};
import { compact, schoolShort, titleCase } from "./athleteContext";
export type RecordKind = "said" | "found" | "made" | "proof";
export type RecordAction = "change" | "tell_mila" | "history" | "link";

export interface RecordEntry {
  /** Stable key. For editable rows this is the ledger field name. */
  field: string;
  label: string;
  /** One line to show, or null when we have nothing ("Not yet"). */
  value: string | null;
  /** The typed value for editors: a line, a list, or an object. Absent for read-only rows. */
  raw?: unknown;
  kind: RecordKind | null;
  /** Human source: "you said", "you told Mila", "found online", "from Instagram", "computed". */
  source: string | null;
  at: string | null;
  /** True when the row can be typed over (a said/found fact with a ledger field). */
  editable: boolean;
  actions: RecordAction[];
  /** For "link" rows: the app screen that owns the detail. */
  link?: "score" | "rates" | "growth" | "deals" | "connections" | "deal_preferences";
  /** For editable rows: the shape the editor should offer. */
  shape?: AssertedShape;
}

export interface RecordGroup {
  key: "who" | "teams" | "want" | "story" | "found" | "numbers" | "connections";
  title: string;
  entries: RecordEntry[];
}

export interface AthleteRecord {
  athleteId: string;
  header: { name: string; identityLine: string; displayScore: number | null; tier: string | null; photoUrl: string | null };
  groups: RecordGroup[];
  counts: { said: number; found: number; made: number; proof: number };
}

const iso = (d: Date | string | null | undefined): string | null => (d ? new Date(d).toISOString() : null);

function editable(field: AssertedField, spec: AssertedFieldSpec): Pick<RecordEntry, "editable" | "actions" | "shape"> {
  return { editable: true, actions: ["change", "tell_mila", "history"], shape: spec.shape };
}

/** A said row from the ledger when present, else the fallback (a signup column or a found fact). */
function saidOr(
  field: AssertedField,
  said: Map<string, Awaited<ReturnType<typeof latestAssertions>>[number]>,
  fallback: { value: string | null; raw?: unknown; kind: RecordKind | null; source: string | null; at: string | null },
): RecordEntry {
  const spec = ASSERTED_FIELDS[field] as AssertedFieldSpec;
  const s = said.get(field);
  if (s) {
    const how = s.source === "settings" ? "you changed it" : s.mode === "voice" ? "you told Mila" : s.source === "onboarding" ? "you told Mila" : "you said";
    return { field, label: spec.label, value: s.value, raw: s.raw, kind: "said", source: how, at: iso(s.at), ...editable(field, spec) };
  }
  return { field, label: spec.label, value: fallback.value, raw: fallback.raw, kind: fallback.value ? fallback.kind : null, source: fallback.value ? fallback.source : null, at: fallback.value ? fallback.at : null, ...editable(field, spec) };
}

const readOnly = (field: string, label: string, value: string | null, kind: RecordKind | null, source: string | null, at: string | null, link?: RecordEntry["link"]): RecordEntry =>
  ({ field, label, value, kind: value ? kind : null, source: value ? source : null, at: value ? at : null, editable: false, actions: link ? ["link"] : [], ...(link ? { link } : {}) });

/** The record: the pre-2d reader (blob + projection). */
export async function getAthleteRecord(athleteId: string): Promise<AthleteRecord | null> {
  return getAthleteRecordLegacy(athleteId);
}

/** The pre-2d reader (blob + projection). */
export async function getAthleteRecordLegacy(athleteId: string): Promise<AthleteRecord | null> {
  const [a] = await db.select({
    full_name: athletes.full_name, first_name: athletes.first_name, sport: athletes.sport, school: athletes.school,
    division: athletes.division, conference: athletes.conference, segment: athletes.segment, photo_url: athletes.photo_url,
    goal_archetype: athletes.goal_archetype, secondary_goals: athletes.secondary_goals, brand_voice: athletes.brand_voice, career_status: athletes.career_status,
    socials: athletes.socials, created_at: athletes.created_at,
  }).from(athletes).where(eq(athletes.id, athleteId)).limit(1);
  if (!a) return null;

  // Non-score fields only (legacy retirement P2-3); followers come from the social substrate.
  const [cur] = await db.select({
    research_updated_at: athletesCurrent.research_updated_at, story_arc: athletesCurrent.story_arc,
  }).from(athletesCurrent).where(eq(athletesCurrent.athlete_id, athleteId)).limit(1);
  const followers = await readFollowers(athleteId);

  // The score itself is the ledger read of record, never legacy display_score/tier/capitals
  // (retired; c04 legacy retirement map item 2.4). There is no modern replacement for the four
  // legacy capitals, so that row is dropped rather than shown mislabeled as M.I.A.
  const mi = await buildMyIntelligence(athleteId);
  const miScore = mi.assessment?.score ?? null;

  const [snap] = await db.select({ research: athleteSnapshots.research, created_at: athleteSnapshots.created_at })
    .from(athleteSnapshots)
    .where(and(eq(athleteSnapshots.athlete_id, athleteId), sql`${athleteSnapshots.research} IS NOT NULL`))
    .orderBy(desc(athleteSnapshots.created_at)).limit(1);
  const research = (snap?.research ?? {}) as {
    achievements?: Array<{ name?: unknown; year?: unknown; level?: unknown }>;
    press_mentions?: Array<{ outlet?: unknown; headline?: unknown }>;
    brand_mentions?: Array<{ brand?: unknown }>;
    causes?: Array<{ name?: unknown }>; values?: Array<{ name?: unknown }>;
    class_year?: unknown; hometown?: unknown; position?: unknown;
  };
  const researchedAt = iso(snap?.created_at);

  const [saidRows, looks, conns, partnerRows, teams] = await Promise.all([
    latestAssertions(athleteId),
    latestFirstLooks(athleteId),
    db.select({ platform: connectedAccounts.platform, username: connectedAccounts.platform_username, status: connectedAccounts.status })
      .from(connectedAccounts).where(eq(connectedAccounts.athlete_id, athleteId)),
    db.select({ brand: deals.brand_name, source: deals.source }).from(deals)
      .where(and(eq(deals.athlete_id, athleteId), inArray(deals.status, EARNED as unknown as string[]))).catch(() => []),
    listAffiliations(athleteId).catch(() => []),
  ]);
  // Deduped by name (case-insensitive), the accepted row's own casing kept.
  const seenBrand = new Set<string>();
  const partners = (partnerRows as Array<{ brand: string | null; source: string | null }>).filter((r) => {
    const k = (r.brand ?? "").trim().toLowerCase();
    if (!k || seenBrand.has(k)) return false;
    seenBrand.add(k); return true;
  });
  const partnerNames = partners.map((r) => String(r.brand).trim());
  const partnersAllConfirmed = partners.length > 0 && partners.every((r) => (ATHLETE_CONFIRMED as readonly string[]).includes(r.source ?? ""));
  const said = new Map(saidRows.map((s) => [s.field, s]));

  // Latest connected analytics per platform (followers, audience) — the Growth tab owns the detail.
  const analytics = await db.select({
    platform: socialAnalyticsSnapshots.platform, followers: socialAnalyticsSnapshots.followers,
    gender: socialAnalyticsSnapshots.top_audience_gender, age: socialAnalyticsSnapshots.top_audience_age_range,
    city: socialAnalyticsSnapshots.top_audience_city, day: socialAnalyticsSnapshots.snapshot_date,
  }).from(socialAnalyticsSnapshots)
    .where(and(eq(socialAnalyticsSnapshots.athlete_id, athleteId), eq(socialAnalyticsSnapshots.source, "connected")))
    .orderBy(desc(socialAnalyticsSnapshots.snapshot_date)).limit(9);
  const latestBy = new Map<string, (typeof analytics)[number]>();
  for (const r of analytics) if (!latestBy.has(r.platform)) latestBy.set(r.platform, r);
  const ig = latestBy.get("instagram") ?? analytics[0];

  // ── who you are ──
  const achievements = (research.achievements ?? []).map((x) => ({ name: String(x?.name ?? "").trim(), year: x?.year != null ? String(x.year) : null, level: typeof x?.level === "string" ? x.level : null })).filter((x) => x.name);
  const marquee = achievements[0] ?? null;
  const identityLine = [a.sport ? titleCase(a.sport) : "", schoolShort(a.school ?? ""), marquee && /world cup|national|olympic|u-\d\d/i.test(marquee.name) ? marquee.name : ""].filter(Boolean).join(" · ");
  const handles = (a.socials ?? {}) as Record<string, unknown>;
  const connected = conns.filter((c) => c.status === "active");
  // One line, handles deduped: "@athletehandle (Instagram, TikTok) · @mia_b (YouTube)".
  const byHandle = new Map<string, string[]>();
  for (const p of ["instagram", "tiktok", "youtube", "twitter"] as const) {
    const c = connected.find((x) => x.platform === (p === "twitter" ? "x" : p));
    const h = c?.username ?? (typeof handles[p] === "string" ? String(handles[p]) : null);
    if (!h) continue;
    const key = `@${String(h).replace(/^@/, "")}`;
    byHandle.set(key, [...(byHandle.get(key) ?? []), p === "twitter" ? "X" : titleCase(p)]);
  }
  const handleLine = [...byHandle.entries()].map(([h, ps]) => `${h} (${ps.join(", ")})`).join(" · ");

  const who: RecordEntry[] = [
    readOnly("name", "Name", a.full_name, "said", "signup", iso(a.created_at)),
    saidOr("nickname", said, { value: a.first_name?.trim() || null, kind: "said", source: "signup", at: iso(a.created_at) }),
    readOnly("photo", "Photo", a.photo_url ? "On file" : null, "found", "your sign-in", null, "connections"),
    saidOr("sport", said, { value: a.sport ? titleCase(a.sport) : null, kind: "said", source: "signup", at: iso(a.created_at) }),
    saidOr("school", said, { value: a.school ?? null, kind: "said", source: "signup", at: iso(a.created_at) }),
    // Declared, never inferred. The column holds the slug; a ledger row adds the year and her words.
    saidOr("career_status", said, { value: careerStatusLabel(a.career_status) ?? "Playing", raw: { status: a.career_status ?? "active", since: null }, kind: "said", source: "signup", at: iso(a.created_at) }),
    readOnly("division", "Division · conference", [a.division, a.conference].filter(Boolean).join(" · ") || null, "found", "found online", researchedAt),
    readOnly("level", "Level", a.segment ? titleCase(a.segment.replace(/_/g, " ")) : null, "made", "from your team", null),
    saidOr("position", said, { value: typeof research.position === "string" ? research.position : null, kind: "found", source: "found online", at: researchedAt }),
    saidOr("class_year", said, { value: research.class_year != null ? String(research.class_year) : null, kind: "found", source: "found online", at: researchedAt }),
    saidOr("hometown", said, { value: typeof research.hometown === "string" ? research.hometown : null, kind: "found", source: "found online", at: researchedAt }),
    readOnly("credential", "Marquee credential", marquee?.name ?? null, "found", "found online", researchedAt),
    readOnly("handles", "Handles", handleLine || null, "said", connected.length ? `${connected.length} connected` : "signup", null, "connections"),
  ];

  // ── your teams (0041) — current first, primary first; past teams muted by their label ──
  // The editor works on the WHOLE list (said + found + proof rows, as team objects); saving writes
  // it back as the athlete's said list, so keeping a found team is how she confirms it.
  const teamList = teams.map((t) => ({
    org: t.org, kind: t.kind, level: t.level, conference: t.conference, role: t.role, position: t.position,
    from: t.from, to: t.to, primary: t.primary, fact: t.kindOfFact,
  }));
  const teamRows: RecordEntry[] = teams.map((t, i) => {
    const span = t.to ? `${t.from ? t.from.slice(0, 4) + "–" : ""}${t.to.slice(0, 4)}` : t.from ? `since ${t.from.slice(0, 4)}` : null;
    const meta = [t.role, t.position, span].filter(Boolean).join(" · ");
    return {
      ...readOnly(
        `team_${i}`,
        t.current ? (t.primary ? "Team · current · primary" : "Team · current") : "Team · past",
        displayTeam(t),
        t.kindOfFact,
        [meta || null, t.source === "signup" ? "signup" : t.kindOfFact === "found" ? "found online" : t.source === "onboarding" ? "you told Mila" : t.source === "settings" ? "you changed it" : t.source].filter(Boolean).join(" · ") || null,
        null,
      ),
      // Tapping a team opens the team editor on this row; `raw` carries the row and the whole list.
      editable: true, actions: ["change", "tell_mila", "history"], shape: "teams" as const,
      raw: { index: i, team: teamList[i], teams: teamList },
    };
  });
  // The "add" row: same editor, no row selected. History/Tell Mila apply to the list as one fact.
  const teamsEditor = saidOr("affiliations", said, { value: null, kind: null, source: null, at: null });
  const addRow: RecordEntry = { ...teamsEditor, label: teamRows.length ? "Add a team" : "Teams", value: null, raw: { index: null, team: null, teams: teamList } };
  const teamsGroup: RecordEntry[] = [...teamRows, addRow];

  // ── what you want ──
  const secondary = Array.isArray(a.secondary_goals) ? (a.secondary_goals as unknown[]).filter((x): x is string => typeof x === "string") : [];
  const want: RecordEntry[] = [
    saidOr("goal", said, { value: goalLabel(a.goal_archetype), raw: a.goal_archetype ?? undefined, kind: "said", source: "signup", at: iso(a.created_at) }),
    saidOr("secondary_goals", said, { value: secondary.length ? secondary.map(goalLabel).join(", ") : null, raw: secondary.length ? secondary : undefined, kind: "said", source: "signup", at: iso(a.created_at) }),
    saidOr("brands_wanted", said, { value: null, kind: null, source: null, at: null }),
    saidOr("never_post", said, { value: null, kind: null, source: null, at: null }),
    saidOr("cadence", said, { value: cadenceText(looks[0]?.posts_per_week), kind: "found", source: `from ${looks[0]?.platform ?? "your posts"}`, at: null }),
    readOnly("deal_preferences", "Deal types you take", null, null, null, null, "deal_preferences"),
    readOnly("floor", "The least you'll take", null, null, null, null, "rates"),
  ];
  // Goals are stored as slugs whichever door wrote them (signup column or the ledger); the
  // screen shows the label. `raw` keeps the slug(s) so the editor round-trips.
  for (const e of want) {
    if (e.field === "goal" && typeof e.raw === "string") e.value = goalLabel(e.raw);
    if (e.field === "secondary_goals" && Array.isArray(e.raw)) e.value = (e.raw as string[]).map(goalLabel).join(", ") || null;
  }

  // ── your story (the said half now; the made half arrives with the layer) ──
  const voice = a.brand_voice as { tone?: string; phrases?: string[]; avoid?: string[] } | null;
  const voiceLine = voice ? [voice.tone, voice.phrases?.length ? `says: ${voice.phrases.join(", ")}` : null, voice.avoid?.length ? `avoids: ${voice.avoid.join(", ")}` : null].filter(Boolean).join(" · ") : null;
  const story: RecordEntry[] = [
    // No kit hook: generated media-kit copy is downstream artifact output, never her story or a source (30 Sep 2026).
    readOnly("narrative", "Story", cur?.story_arc ?? null, "made", "written from research", iso(cur?.research_updated_at)),
    readOnly("stories", "Your stories", null, null, null, null),
    saidOr("brands_causes", said, { value: null, kind: null, source: null, at: null }),
    saidOr("hobbies", said, { value: null, kind: null, source: null, at: null }),
    saidOr("note", said, { value: null, kind: null, source: null, at: null }),
    saidOr("brand_voice", said, { value: voiceLine, raw: voice ?? undefined, kind: "said", source: "you confirmed", at: null }),
  ];

  // ── what we found ──
  const brandsSeen = [...new Set((research.brand_mentions ?? []).map((b) => String(b?.brand ?? "").trim()).filter(Boolean))];
  const causes = [...new Set(((research.values ?? research.causes ?? []) as Array<{ name?: unknown }>).map((c) => String(c?.name ?? "").trim()).filter(Boolean))];
  const found: RecordEntry[] = [
    readOnly("achievements", "Achievements", achievements.length ? achievements.slice(0, 5).map((x) => x.year ? `${x.name} (${x.year})` : x.name).join(" · ") : null, "found", `${achievements.length} found online`, researchedAt),
    readOnly("press", "Press", research.press_mentions?.length ? `${research.press_mentions.length} mentions` : null, "found", "found online", researchedAt),
    readOnly("brands_seen", "Brands seen with you", brandsSeen.length ? brandsSeen.slice(0, 6).join(", ") : null, "found", "found online", researchedAt, "deals"),
    readOnly("confirmed", "Confirmed relationships", partnerNames.length ? partnerNames.join(", ") : null, "proof",
      partnerNames.length ? (partnersAllConfirmed ? "contract on file" : "accepted deal · from your inbox") : "contract on file or accepted deal", null, "deals"),
    readOnly("causes_seen", "Causes seen with you", causes.length ? causes.slice(0, 4).join(", ") : null, "found", "found online", researchedAt),
    ...looks.map((l) => readOnly(`first_look_${l.platform}`, titleCase(l.platform), [
      l.themes.length ? l.themes.join(", ") : null,
      `${l.posts_read} posts read`,
      cadenceText(l.posts_per_week),
      l.tagged.length ? `tags ${l.tagged.map((t) => `@${t}`).join(", ")}` : null,
    ].filter(Boolean).join(" · "), "found", `from your ${l.platform} posts`, null, "growth")),
    readOnly("followers", "Followers", followersLine(followers), "found", "connected accounts", followers.asOf, "growth"),
    readOnly("audience", "Audience", ig ? [ig.gender ? (ig.gender === "F" ? "mostly women" : ig.gender === "M" ? "mostly men" : ig.gender) : null, ig.age, ig.city].filter(Boolean).join(" · ") || null : null, "found", "from Instagram", iso(ig?.day), "growth"),
  ];

  // ── your numbers ──
  // Legacy retirement, phase 1 (owner decision 8 Oct 2026): the computed rate card row is gone — rates are being
  // rebuilt, and her own floor is the "floor" row under What you want.
  const numbers: RecordEntry[] = [
    readOnly("score", "Score", miScore != null ? String(miScore) : null, "made", "computed", mi.assessment?.evidenceAsOf ?? null, "score"),
  ];

  // ── connections ──
  const connections: RecordEntry[] = connected.length
    ? connected.map((c) => readOnly(`conn_${c.platform}`, titleCase(c.platform), c.username ? (c.username.includes("@") && !c.username.startsWith("@") ? c.username : `@${c.username.replace(/^@/, "")}`) : "Connected", "found", "connected", null, "connections"))
    : [readOnly("conn_none", "Accounts", null, null, null, null, "connections")];

  const groups: RecordGroup[] = [
    { key: "who", title: "Who you are", entries: who },
    { key: "teams", title: "Your teams", entries: teamsGroup },
    { key: "want", title: "What you want", entries: want },
    { key: "story", title: "Your story", entries: story },
    { key: "found", title: "What we found", entries: found },
    { key: "numbers", title: "Your numbers", entries: numbers },
    { key: "connections", title: "Connections", entries: connections },
  ];
  const all = groups.flatMap((g) => g.entries).filter((e) => e.value);
  return {
    athleteId,
    header: { name: a.full_name, identityLine, displayScore: miScore, tier: null, photoUrl: a.photo_url ?? null },
    groups,
    counts: {
      said: all.filter((e) => e.kind === "said").length,
      found: all.filter((e) => e.kind === "found").length,
      made: all.filter((e) => e.kind === "made").length,
      proof: all.filter((e) => e.kind === "proof").length,
    },
  };
}

export interface RecordHistoryItem {
  agent_action_id: string;
  at: string | null;
  from: unknown;
  to: unknown;
  mode: string | null;
  source: string | null;
  undone_at: string | null;
  reversible: boolean;
}

/** Every receipt for one field, newest first — the row's History sheet, each with Undo. */
export async function getFieldHistory(athleteId: string, field: string, limit = 50): Promise<RecordHistoryItem[]> {
  const rows = await db.select().from(agentActions)
    .where(and(eq(agentActions.athlete_id, athleteId), inArray(agentActions.action, ["profile_write"]), sql`${agentActions.payload}->>'field' = ${field}`))
    .orderBy(desc(agentActions.created_at)).limit(limit);
  return rows.map((r) => {
    const p = (r.payload ?? {}) as Record<string, unknown>;
    return {
      agent_action_id: r.id, at: iso(r.created_at), from: p.from ?? null, to: p.to ?? null,
      mode: typeof p.mode === "string" ? p.mode : null, source: typeof p.source === "string" ? p.source : null,
      undone_at: iso(r.undone_at), reversible: r.reversible,
    };
  });
}
